var i=`0761-mukimo`;var t=`world-0761`;var s=`KE`;var o=`eastern-africa`;var a=4;var r=60;var u={en:`Mukimo`,ua:`Мукімо`};var l={en:`Mukimo is a Kenya classic prepared with potato, spinach, green onion, fresh corn kernels. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Мукімо, страва кухні країни Кенія зі складниками: картопля, шпинат, зелена цибуля, зерна свіжої кукурудзи. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 27 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 27 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:27,i:[[`potato`,720,`g`],[`water`,950,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`spinach`,290,`g`],[`green-onion`,100,`g`],[`sunflower-oil`,28,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 10 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 10 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:10,i:[[`fresh-corn-kernels`,200,`g`],[`frozen-green-peas`,170,`g`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 12 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 12 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:12,i:[[`unsalted-butter`,60,`g`],[`table-salt`,null,`to_taste`]]}];var g={slug:i,id:t,country:`KE`,region:o,servings:4,minutes:60,title:u,text:l,steps:d};export{s as country,g as default,t as id,r as minutes,o as region,a as servings,i as slug,d as steps,l as text,u as title};